import math
# Include the previously defined functions for completeness
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def phi(n):
    if n == 1:
        return 1
    result = n
    p = 2
    temp_n = n
    while p * p <= temp_n:
        if temp_n % p == 0:
            while temp_n % p == 0:
                temp_n //= p
            result -= result // p
        p += 1
    if temp_n > 1:
        result -= result // temp_n
    return result

def order_3_mod_n(n):
    if math.gcd(3, n) != 1:
        return 0

    phi_n = phi(n)

    divisors = set()
    for i in range(1, int(math.sqrt(phi_n)) + 1):
        if phi_n % i == 0:
            divisors.add(i)
            divisors.add(phi_n // i)

    for k in sorted(list(divisors)):
        if k == 0: continue
        if pow(3, k, n) == 1:
            return k
    return phi_n

def count_cycles(m):
    if m <= 1 or m % 3 == 0:
        return None # Indicate invalid m

    divisors = set()
    for i in range(2, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.add(i)
            divisors.add(m // i)
    divisors.add(m)

    total_cycles = 0

    for d in divisors:
        if d == 1:
            continue

        order = order_3_mod_n(d)
        if order == 0:
            continue

        term = phi(d) // order
        total_cycles += term

    return total_cycles

# Search for the second largest m < 200 (i.e., m <= 199) such that count_cycles(m) is odd.
valid_m_with_odd_cycles = []
for m in range(1, 200):
    if m % 3 == 0:
        continue

    cycles = count_cycles(m)

    if cycles is not None and cycles % 2 != 0:
        valid_m_with_odd_cycles.append(m)

# Sort in descending order and pick the second element
valid_m_with_odd_cycles.sort(reverse=True)

if len(valid_m_with_odd_cycles) >= 2:
    second_largest_m = valid_m_with_odd_cycles[1]
    print(f"All m < 200 not divisible by 3 with odd number of cycles: {valid_m_with_odd_cycles}")
    print(f"The second largest such m is: {second_largest_m}")
